"""Demo project «Демо: участок Северный» (ТЗ 7.5). Ported from BF demo.py: the data are generated by code with
a fixed seed (no files, no network), so every installation gets the same project.

Parts are added by the stages that bring their data types: drillholes and AU/CU assays (Э3), the audit with
deliberate errors (Э5), a trench, strings of the ore body, the road, the survey points, the plan of the site and
the DTM with the plan on it (Э7, `geo.py`), wireframes of the ore body and outlines (Э8), contours on sections with
tie lines, the solid stitched from them and the isolines of the relief (Э9, `contours.py`), the geological map and
the scan of the section Y = 8125 (Э9), the series of sections of «Рудное тело 3» and the plans of the relief (Э10,
`sections.py`), the block model around the ore bodies (Э11, `blocks.py`). A part is a function (conn, store,
rng) registered in PARTS. Then «Композиты 2 м» and «Рудные интервалы» by the bodies of their jobs (Э12,
`samples.py`) and the audit.
"""

from __future__ import annotations

import random
from collections.abc import Callable
from typing import Any

import sqlalchemy as sa

from bf_core.db import dialect
from bf_core.projects.project import Project
from bf_core.projects.store import ProjectService
from bf_core.storage.blobs import BlobStore

DEMO_NAME = "Демо: участок Северный"
DEMO_DESCRIPTION = {"deposit": "Северное (учебное)", "license": "Учебный участок", "stage": "Разведка"}
SEED = 7
#: «Композиты 2 м» and «Рудные интервалы» are made (Э12); the tests of the kernels switch them off (conftest)
SAMPLES = True

Part = Callable[[sa.Connection, BlobStore, random.Random], None]
#: (name, part) in the order of creation; later stages append theirs.
PARTS: list[tuple[str, Part]] = []


def find_demo(svc: ProjectService) -> dict[str, Any] | None:
    key = dialect.name_key(DEMO_NAME)
    return next((e for e in svc.list() if dialect.name_key(e["name"]) == key), None)


def create_or_open(svc: ProjectService) -> tuple[Project, bool]:
    """The demo project; a second call opens the one already made (ТЗ 7.5). Returns (project, created)."""
    existing = find_demo(svc)
    if existing is not None:
        return svc.open(existing["uid"]), False
    project = svc.create(DEMO_NAME, DEMO_DESCRIPTION)
    rng = random.Random(SEED)
    store = BlobStore(project.folder)
    for _name, part in PARTS:
        with dialect.write_tx(project.engine) as conn:
            part(conn, store, rng)
    _samples(project)
    _audit(project)
    return project, True


def _samples(project: Project) -> None:
    """«Композиты 2 м» and «Рудные интервалы» (Э12, `samples.py`): by the bodies of their jobs once the data are
    written, before the audit (ORE_ID / ORE_CLS move the revision of «Пробы» the audit is made for)."""
    import logging

    from .samples import add_samples

    if not SAMPLES:
        return
    try:
        add_samples(project)
    except Exception:  # noqa: BLE001 - the demo opens anyway; the results can be made from «Обработка проб»
        logging.getLogger("bf_core.demo").exception("demo sample processing failed")


def _audit(project: Project) -> None:
    """The demo opens with its audit done (ТЗ 7.5, 7.12): the deliberate errors are listed at once."""
    from bf_core.audit.service import default_table, get_settings, run
    from bf_core.db.schema import objects

    with dialect.read_tx(project.engine) as conn:
        sets = list(conn.execute(sa.select(objects.c.id).where(objects.c.kind == "drillhole_set")).scalars())
        plans = [(s, default_table(conn, s), get_settings(conn, s)["config"]) for s in sets]
    import logging

    for set_id, table, config in plans:
        try:
            run(project.engine, set_id, table=table, config=config, job_id=None, tick=lambda _f, _m=None: None)
        except Exception:  # noqa: BLE001 - the demo opens anyway; the audit can be run from its tab
            logging.getLogger("bf_core.demo").exception("demo audit failed")


def _register() -> None:
    from .blocks import add_blocks
    from .contours import add_contours, add_isolines
    from .drillholes import add_drillholes
    from .geo import add_lines, add_terrain, add_trench
    from .sections import add_plans
    from .wireframes import add_wireframes

    PARTS.append(("drillholes", add_drillholes))
    # Э7 (`geo.py`), after the holes: they take the random stream first and stay as they were
    PARTS.extend([("trench", add_trench), ("lines", add_lines), ("terrain", add_terrain)])
    # Э8 (`wireframes.py`): the ore bodies from the strings of the ore lens and the fault; no random numbers
    PARTS.append(("wireframes", add_wireframes))
    # Э9 (`contours.py`): contours on the sections with tie lines, the solid stitched from them, the isolines of
    # «Рельеф»; no random numbers
    PARTS.extend([("contours", add_contours), ("isolines", add_isolines)])
    # Э10 (`sections.py`): the series of the contours is made with them (`add_contours`), the plans after the
    # isolines they take their levels and contour layer from; no random numbers
    PARTS.append(("plans", add_plans))
    # Э11 (`blocks.py`): the block model around the ore bodies; a generator of its own, not the demo stream
    PARTS.append(("blocks", add_blocks))


_register()
